import * as React from "react";

export interface DragReorderItemProps {
  draggable: true;
  onDragStart: (event: React.DragEvent<HTMLElement>) => void;
  onDragEnter: (event: React.DragEvent<HTMLElement>) => void;
  onDragOver: (event: React.DragEvent<HTMLElement>) => void;
  onDragLeave: (event: React.DragEvent<HTMLElement>) => void;
  onDrop: (event: React.DragEvent<HTMLElement>) => void;
  onDragEnd: (event: React.DragEvent<HTMLElement>) => void;
}

export interface UseDragReorderResult {
  /** Index of the item currently being dragged, or null. */
  draggingIndex: number | null;
  /** Index of the item currently being hovered as a drop target, or null. */
  dragOverIndex: number | null;
  /** Returns drag handlers (and `draggable: true`) for the item at `index`. */
  getItemProps: (index: number) => DragReorderItemProps;
}

/**
 * HTML5 drag-to-reorder. The hook only tracks state -- the caller renders
 * the items and decides what visual feedback to show (e.g., opacity-down on
 * the dragged item, ring on the drop target). Drop semantics:
 * `onReorder(from, to)` is called with indices into the *original* array,
 * and the splice-based caller pattern places the moved item at `to` in the
 * resulting array.
 *
 * Typical usage:
 *
 * ```tsx
 * const reorder = useDragReorder((from, to) => setItems(prev => {
 *   const next = [...prev]
 *   const [m] = next.splice(from, 1)
 *   next.splice(to, 0, m)
 *   return next
 * }))
 *
 * items.map((item, idx) => (
 *   <div
 *     key={item.id}
 *     {...reorder.getItemProps(idx)}
 *     className={cn(
 *       reorder.draggingIndex === idx && "opacity-40",
 *       reorder.dragOverIndex === idx &&
 *         reorder.draggingIndex !== idx &&
 *         "ring-2 ring-accent",
 *     )}
 *   >
 *     {item.content}
 *   </div>
 * ))
 * ```
 */
export function useDragReorder(
  onReorder: (from: number, to: number) => void,
): UseDragReorderResult {
  const [draggingIndex, setDraggingIndex] = React.useState<number | null>(null);
  const [dragOverIndex, setDragOverIndex] = React.useState<number | null>(null);

  // Mirror draggingIndex into a ref so event handlers always read the latest
  // without having to be regenerated on every drag-state change.
  const draggingRef = React.useRef<number | null>(null);
  React.useEffect(() => {
    draggingRef.current = draggingIndex;
  }, [draggingIndex]);

  const onReorderRef = React.useRef(onReorder);
  React.useEffect(() => {
    onReorderRef.current = onReorder;
  }, [onReorder]);

  const getItemProps = React.useCallback((index: number): DragReorderItemProps => ({
    draggable: true,
    onDragStart: (event) => {
      // setData is required for Firefox to actually start the drag.
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", String(index));
      }
      setDraggingIndex(index);
    },
    onDragEnter: (event) => {
      event.preventDefault();
      setDragOverIndex(index);
    },
    onDragOver: (event) => {
      // Both dragOver preventDefault and dropEffect are required for
      // the drop event to fire reliably across browsers.
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = "move";
      }
    },
    onDragLeave: () => {
      // Intentionally a no-op. dragenter on a sibling races with dragleave
      // on the previous; clearing here causes flicker. State is cleared on
      // drop / dragend instead.
    },
    onDrop: (event) => {
      event.preventDefault();
      const from = draggingRef.current;
      const to = index;
      setDraggingIndex(null);
      setDragOverIndex(null);
      if (from === null || from === to) return;
      onReorderRef.current(from, to);
    },
    onDragEnd: () => {
      setDraggingIndex(null);
      setDragOverIndex(null);
    },
  }), []);

  return {
    draggingIndex,
    dragOverIndex,
    getItemProps,
  };
}
